class TestCorrectness(unittest.TestCase):

    def test_scalar_multiplication_selene(self):
        for scalar,result in zip(SELENE_SCALARS,SELENE_RESULT):
            ans = GS * scalar
            self.assertEqual(ans.x,result[0])
            self.assertEqual(ans.y,result[1])

    def test_scalar_multiplication_helios(self):
        for scalar,result in zip(HELIOS_SCALARS,HELIOS_RESULT):
            ans = GH * scalar
            self.assertEqual(ans.x,result[0])
            self.assertEqual(ans.y,result[1])


# ====================== BENCHMARK FUNCTION ======================
def run_benchmark(name: str, base_point: Point, scalars: list[int], num_ops: int = 1):
    print(f"{name} Benchmark ({num_ops} scalar multiplications)")
    print(f"Curve prime: {hex(base_point.curve.p)}")

    start_time = time.perf_counter()

    for i in range(num_ops):
        for scalar in scalars:
            ans = base_point * scalar
            # print(f"{hex(scalar)} * {base_point} = {ans.to_hex()}")
            # print(f"({'0x'+format(ans.x,'064x')},{'0x'+format(ans.y,'064x')}),")
            # import ipdb;ipdb.set_trace()

    elapsed = time.perf_counter() - start_time

    print(f"\nBenchmark completed!")
    print(f"Total time for scalar multiplications: {elapsed:.4f} seconds")
    print(f"Average time per multiplication: {(elapsed / (num_ops * 100) )* 1000:.4f} ms")


# ====================== RUN BENCHMARKS ======================
if __name__ == "__main__":
    print("Helios and Selene benchmark \n")

    # benchmark values
    run_benchmark("Helios", GH, HELIOS_SCALARS)
    run_benchmark("Selene", GS, SELENE_SCALARS)

    # verify correctness
    unittest.main()

    print("\nBenchmark finished.")